@Timeout(60)
class LmdbUploadRecoveryTest {

	private static final String REPOSITORY_ID = "upload-recovery";
	private static final String NAMESPACE = "urn:upload-recovery:";
	private static final String DATA = "<urn:upload-recovery:uploaded> <urn:upload-recovery:p> \"uploaded\" .\n";

	@TempDir
	File directory;

	private SailRepository repository;

	private final TransactionController transactions = new TransactionController();

	private void initializeRepository(LmdbStoreConfig config) {
		repository = new SailRepository(new LmdbStore(directory, config));
		repository.init();
	}

	private void initializeExistingStore(int prefixRows) {
		LmdbStoreConfig config = new LmdbStoreConfig();
		if (prefixRows > 1) {
			// Isolate reading beside a flushed NONE writer from map-growth admission. Under map pressure,
			// independent reads deliberately wait for the old writer to finish; that recovery is tested below.
			config.setTripleDBSize(64L << 20).setValueDBSize(256L << 20);
		}
		initializeRepository(config);
		seedExistingStore();
	}

	private void seedExistingStore() {
		try (var connection = repository.getConnection()) {
			connection.begin();
			connection.setNamespace("ex", NAMESPACE);
			// Use an existing store so the failed request does not hold an exclusive initial run import.
			connection.add(Values.iri(NAMESPACE + "existing"), Values.iri(NAMESPACE + "p"), Values.literal("existing"));
			connection.commit();
		}
	}

	@AfterEach
	void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(ints = { 1, 5_001 })
	void malformedNoneUploadKeepsNamespacesReadableAndAllowsRetryAfterRollback(int prefixRows) throws Exception {
		initializeExistingStore(prefixRows);
		withTransaction(transaction -> {
			assertUploadFailure(transaction, false, prefixRows);
			assertNamespaceReadable(true);
			rollbackOverHttp(transaction);
		});
		assertNamespaceReadable(true);
		assertRetryUpload();
	}

	@ParameterizedTest
	@ValueSource(ints = { 1, 5_001 })
	void disconnectedNoneUploadKeepsNamespacesReadableAndAllowsRetryAfterClose(int prefixRows) throws Exception {
		initializeExistingStore(prefixRows);
		withTransaction(transaction -> {
			assertUploadFailure(transaction, true, prefixRows);
			assertNamespaceReadable(true);
		});
		assertNamespaceReadable(true);
		assertRetryUpload();
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void malformedLargeNoneUploadAllowsRetryAfterRollback(boolean seeded) throws Exception {
		initializeRepository(new LmdbStoreConfig());
		if (seeded) {
			seedExistingStore();
		}
		withTransaction(transaction -> {
			assertUploadFailure(transaction, false, 5_001);
			// Initial imports and map growth can hold independent reads until this explicit transaction ends.
			rollbackOverHttp(transaction);
		});
		assertNamespaceReadable(seeded);
		assertRetryUpload();
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void disconnectedLargeNoneUploadAllowsRetryAfterClose(boolean seeded) throws Exception {
		initializeRepository(new LmdbStoreConfig());
		if (seeded) {
			seedExistingStore();
		}
		// Server-side cleanup must release any initial-import or map-growth gate before the next request.
		withTransaction(transaction -> assertUploadFailure(transaction, true, 5_001));
		assertNamespaceReadable(seeded);
		assertRetryUpload();
	}

	private void assertUploadFailure(Transaction transaction, boolean disconnect, int prefixRows)
			throws Exception {
		String prefix = uploadPrefix(prefixRows);
		MockHttpServletRequest upload = disconnect ? disconnectedRequest(prefix) : new MockHttpServletRequest();
		configureAddRequest(upload, transaction);
		if (disconnect) {
			assertThatThrownBy(() -> transactions.handleRequest(upload, new MockHttpServletResponse()))
					.isInstanceOf(ServerHTTPException.class)
					.hasRootCauseMessage("client disconnected during upload");
		} else {
			upload.setContent((prefix + "<urn:upload-recovery:broken> <urn:upload-recovery:p> \"unterminated")
					.getBytes(UTF_8));
			assertThatThrownBy(() -> transactions.handleRequest(upload, new MockHttpServletResponse()))
					.isInstanceOfSatisfying(ClientHTTPException.class,
							failure -> assertThat(failure.getStatusCode()).isEqualTo(400));
		}

		// Failed ADD does not end an explicit HTTP transaction. The namespace endpoint opens a separate
		// auto-commit connection while the failed NONE transaction still owns its isolation-mode lock.
		assertThat(ActiveTransactionRegistry.INSTANCE.getTransaction(transaction.getID())).isSameAs(transaction);
	}

	private void rollbackOverHttp(Transaction transaction) throws Exception {
		MockHttpServletRequest rollback = new MockHttpServletRequest();
		configureTransactionRequest(rollback, transaction, "DELETE");
		ModelAndView result = transactions.handleRequest(rollback, new MockHttpServletResponse());
		assertThat(result.getView()).isSameAs(EmptySuccessView.getInstance());
		assertTransactionClosed(transaction);
	}

	private void assertTransactionClosed(Transaction transaction) {
		assertThat(transaction.isClosed()).isTrue();
		assertThat(transaction.isComplete()).isTrue();
		assertThatThrownBy(() -> ActiveTransactionRegistry.INSTANCE.getTransaction(transaction.getID()))
				.isInstanceOf(RepositoryException.class)
				.hasMessageContaining("not registered");
	}

	private void assertRetryUpload() throws Exception {
		withTransaction(transaction -> {
			MockHttpServletRequest upload = new MockHttpServletRequest();
			configureAddRequest(upload, transaction);
			upload.setContent(DATA.getBytes(UTF_8));
			ModelAndView result = transactions.handleRequest(upload, new MockHttpServletResponse());
			assertThat(result.getModel()).containsEntry(SimpleResponseView.SC_KEY, 200);
			MockHttpServletRequest commit = new MockHttpServletRequest();
			configureTransactionRequest(commit, transaction, "PUT");
			commit.setParameter(Protocol.ACTION_PARAM_NAME, "COMMIT");
			ModelAndView committed = transactions.handleRequest(commit, new MockHttpServletResponse());
			assertThat(committed.getModel()).containsEntry(SimpleResponseView.SC_KEY, 200);
			assertTransactionClosed(transaction);
		});
		try (var connection = repository.getConnection()) {
			assertThat(connection.hasStatement(Values.iri(NAMESPACE + "uploaded"), Values.iri(NAMESPACE + "p"),
					Values.literal("uploaded"), false)).isTrue();
		}
	}

	private void assertNamespaceReadable(boolean exists) throws Exception {
		String path = "/repositories/" + REPOSITORY_ID + "/namespaces/ex";
		MockHttpServletRequest request = new MockHttpServletRequest("GET", path);
		request.setPathInfo(path);
		request.setAttribute("repositoryID", REPOSITORY_ID);
		request.setAttribute("repository", repository);
		if (exists) {
			ModelAndView result = new NamespaceController().handleRequest(request, new MockHttpServletResponse());
			assertThat(result.getModel()).containsEntry(SimpleResponseView.CONTENT_KEY, NAMESPACE);
		} else {
			assertThatThrownBy(() -> new NamespaceController().handleRequest(request, new MockHttpServletResponse()))
					.isInstanceOfSatisfying(ClientHTTPException.class,
							failure -> assertThat(failure.getStatusCode()).isEqualTo(404));
		}
	}

	private static String uploadPrefix(int rows) {
		StringBuilder data = new StringBuilder();
		for (int row = 0; row < rows; row++) {
			data.append("<urn:upload-recovery:failed/")
					.append(row)
					.append("> <urn:upload-recovery:p> \"prefix\" .\n");
		}
		return data.toString();
	}

	private void configureAddRequest(MockHttpServletRequest request, Transaction transaction) {
		configureTransactionRequest(request, transaction, "PUT");
		request.setContentType(RDFFormat.NTRIPLES.getDefaultMIMEType());
		request.setParameter(Protocol.ACTION_PARAM_NAME, "ADD");
	}

	private void configureTransactionRequest(MockHttpServletRequest request, Transaction transaction, String method) {
		String path = "/repositories/" + REPOSITORY_ID + "/transactions/" + transaction.getID();
		request.setMethod(method);
		request.setRequestURI(path);
		request.setPathInfo(path);
	}

	private MockHttpServletRequest disconnectedRequest(String data) {
		InputStream failingInput = new InputStream() {
			private final ByteArrayInputStream prefix = new ByteArrayInputStream(data.getBytes(UTF_8));

			@Override
			public int read() throws IOException {
				int value = prefix.read();
				if (value < 0) {
					throw new IOException("client disconnected during upload");
				}
				return value;
			}

			@Override
			public int read(byte[] bytes, int offset, int length) throws IOException {
				int count = prefix.read(bytes, offset, length);
				if (count < 0) {
					throw new IOException("client disconnected during upload");
				}
				return count;
			}
		};
		return new MockHttpServletRequest() {
			private final ServletInputStream input = new DelegatingServletInputStream(failingInput);

			@Override
			public ServletInputStream getInputStream() {
				return input;
			}
		};
	}

	private void withTransaction(TransactionOperation operation) throws Exception {
		try (Transaction transaction = new Transaction(repository)) {
			transaction.begin(IsolationLevels.NONE);
			ActiveTransactionRegistry.INSTANCE.register(transaction);
			try {
				operation.execute(transaction);
			} finally {
				// Deregistration closes the connection, just like server cleanup of an abandoned upload.
				if (!transaction.isClosed()) {
					ActiveTransactionRegistry.INSTANCE.deregister(transaction);
				}
			}
		}
	}

	@FunctionalInterface
	private interface TransactionOperation {
		void execute(Transaction transaction) throws Exception;
	}
}
